def count(w):
    n=0; src=[]; ctx=''
    pat=re.compile(r'(?<![\wͰ-Ͽ])'+re.escape(w.strip())+r'(?![\wͰ-Ͽ])') if w.strip()==w else re.compile(re.escape(w))
    for s in c:
        k=len(pat.findall(s['text']))
        if k:
            n+=k; src.append(s['src'])
            if not ctx:
                m=pat.search(s['text']); ctx=s['text'][max(0,m.start()-45):m.end()+45].replace('\n',' ')
    return n,sorted(set(src)),ctx
def write_csv(path,header,rows):
    buf=io.StringIO()
    wr=csv.writer(buf,delimiter='^',quotechar='"',quoting=csv.QUOTE_MINIMAL,lineterminator='\r\n')
    wr.writerow(header); wr.writerows(rows)
    open(path,'w',encoding='utf-8-sig',newline='').write(buf.getvalue())
rows=[]; i=0; miss=[]
for w,r,cert,note in fixes:
    n,src,ctx=count(w)
    if n==0: miss.append(w); continue
    i+=1
    rows.append([i,w.strip(),r.strip(),cert,n,len(src),' | '.join(src[:3])+(' …' if len(src)>3 else ''),'…'+ctx+'…',note,'ΝΑΙ' if cert==S else ''])
write_csv('/home/claude/ygeiognosia/archive/review/orthografia.csv',['Α/Α','Όπως είναι','Διόρθωση','Βεβαιότητα','Εμφανίσεις','Σελίδες','Σελίδες (δείγμα)','Απόσπασμα','Σημείωση','Έγκριση (ΝΑΙ/ΟΧΙ)'],rows)
